/** The Phosphor grid every path is drawn on. */
internal const val PHOSPHOR_GRID = 256f

private val PhosphorCache = HashMap<Pair<OwnTVIcon, Boolean>, Path>()

/** [icon] as a Phosphor path on the 256 grid ([filled]: the fill weight when there is one), or null. */
internal fun phosphorPath(icon: OwnTVIcon, filled: Boolean = false): Path? {
    val key = icon to filled
    PhosphorCache[key]?.let { return it }
    val data = (if (filled) PhosphorFill[icon] else null) ?: PhosphorRegular[icon] ?: return null
    return PathParser().parsePathString(data).toPath().also { PhosphorCache[key] = it }
}
